add(pid,title='Solvent response and hydrogen-bond controls for dyes 3 and 4',species=sp,
 objective='Test whether bulk dielectric stabilization, specific methanol hydrogen bonding, or a change in transition identity explains the three-solvent response of phenolate dyes 3 and 4. Separate substituent and solvent effects with a held-out methanol prediction and a stoichiometrically matched micro-solvation control.',
 boundary='Dye3 and dye4 differ by a terminal nitrothiophene versus nitrophenyl group. They are not positional isomers and do not share an elemental formula. Retain the E imine, q=-1 singlet and no counterion. Three solvents cannot locate a continuous inversion point or support a four-parameter Catalan fit. Molecular spectra do not establish bulk ion-pair or device behavior.',
 controls={'solvent_panel':solvents,'holdout':'Freeze continuum method, state-matching rule, broadening and any global offset from toluene/ethyl acetate before revealing methanol error. This is a retrospective holdout, not a claim that source observations were unseen.','cluster_definition':'For each dye add exactly one neutral methanol. Initialize phenolate O···H-O(MeOH) hydrogen-bonded placement at O···H=1.8 Å and a remote placement with methanol O at least 5 Å from every dye heteroatom; optimize independently in methanol continuum. Distance is an initialization, not a presumed minimum. If both collapse to one basin, retain trajectory evidence and use a remote constrained single point as the non-H-bond electronic control, not an equilibrium species.','atom_mapping':'Dye+MeOH graph is the disconnected union with unique maps. Retain the dye common phenolate-imine-phenylene subgraph between dyes; ring replacement atoms are explicitly unmatched.'},
 data={'experimental_bands.json':{'source':'SI PDF p5 Table S2, lower-energy absorption band; higher band in Table S1 is a different observable','unit':'kcal/mol photon energy','calibration_solvents':{'toluene':{'dye3':57.76,'dye4':61.75},'ethyl_acetate':{'dye3':52.94,'dye4':59.44}},'holdout_methanol':{'dye3':63.39,'dye4':69.23},'conversion':'1 eV = 23.06055 kcal/mol; wavelength_nm = 28591.43 / energy_kcal_mol','source_discrepancy':'Main DCM lower-band value differs from SI; DCM is outside the required three-solvent matrix, so no inconsistent target is fitted.'}},
 public_sources=['Main PDF p2 structure figure identifies terminal rings; pp3–4 solvent response and computational method.','SI pp3–5 distinguish two bands and provide solvent observations.'],author='The authors interpret positive/negative solvatochromism in terms of solvent polarity, donor–acceptor charge redistribution and specific interactions. The source calculation uses ωB97X-D4/def2-TZVP with CPCM and vertical excitations. Use this as the baseline hypothesis; the matched one-methanol controls and frozen holdout/state-discrimination test are new.',
 panels=[panel('continuum','Two dyes in three identical solvent treatments',table(['dye3','dye4'],table(solvents,transition)), 'Minimum-validate both dye graphs in toluene, ethyl acetate and methanol at a shared continuum protocol. Report a state window, energies/f and NTO or equivalent electron-hole descriptors. Follow corresponding character rather than silently comparing root1 to a different state. Check a diffuse basis sensitivity for the anion.',25),panel('micro_solvation','Hydrogen-bond versus remote methanol control',table(['dye3','dye4'],O(hbond=row(excitation_eV=N(),O_H_distance_A=N(),geometry_role=E('relaxed_minimum','constrained_control'),state_match=S(),binding_reference=S()),remote=collapse(row(excitation_eV=N(),O_H_distance_A=N(),geometry_role=E('relaxed_minimum','constrained_control'),state_match=S(),binding_reference=S())),matched_electronic_difference=row(delta_excitation_eV=N(),common_geometry_definition=S(),stoichiometry=C('dye_minus_plus_one_neutral_methanol')))), 'Use exactly one MeOH in both cluster placements with explicit atom correspondence and state matching. Separate relaxed cluster changes from fixed-geometry electronic differences. Demonstrated collapse/dissociation is an outcome; if using a constrained remote geometry do not assign Boltzmann population or claim it is a minimum.',20),panel('heldout_and_attribution','Frozen prediction and competing explanations',table(['dye3','dye4'],row(frozen_protocol_file=P,predicted_MeOH_kcal_mol=N(),observed_MeOH_kcal_mol=N(),residual_kcal_mol=N(),bulk_only_prediction=N(),specific_interaction_correction=N(),state_switch_diagnostic=S(),interpretation=S())), 'Preserve a pre-holdout protocol artifact; calculate methanol residuals without per-dye refitting. Contrast continuum-only, specific-interaction and state-switch explanations using the controlled differences. Quantify uncertainty and avoid identifying an exact inversion threshold from three solvents.',20)],conclusion='Bound how far continuum polarity alone explains the response and whether micro-solvation/state identity is needed.',critical=['Dye3/4 are called positional isomers or the two experimental absorption bands are confused.','Clusters with different solvent count/charge are compared as a hydrogen-bond effect without a consistent reference.','Methanol is used to tune the prediction then reported as an independent holdout.'],pages={'paper_main':[2,3,4],'paper_si':[3,4,5]},source_review={'paper_main':'Structure figure inspected visually: nitrothiophene versus nitrophenyl; solvent discussion and source DFT route read.','paper_si':'Lower/higher band tables read and three-solvent numerical observations transcribed; DCM discrepancy isolated from required comparison.'},legacy='Original E-dye3 phenolate identity and single-solvent TD setup are reusable. The old DCM-only scalar is not a reference for the expanded solvent matrix.',gaps='Dye4, all matched-solvent states, one-MeOH controls and frozen prediction residuals need reference calculations.',pilot='Validate dye4 connectivity and one dye3 methanol cluster; check state matching and diffuse-basis stability before all six continuum jobs.',software='Gaussian/ORCA continuum TDDFT, explicit one-MeOH cluster optimization and NTO analysis; no new empirical bulk-solvent model required.',corrections=['First-version wording of position isomers corrected from the actual structural figure: terminal nitrothiophene/nitrophenyl substitution changes composition.'])

